ORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, LAST_15_DAYS_SALES, LEAST(LAST_15_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM LAST45D_STR WHERE SNAPSHOT_DATE = CURRENT_DATE - 45 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), last_60 AS ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ), LAST60D_STR AS ( SELECT I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE AS SNAPSHOT_DATE, I.INVENTORY AS OPENING_INVENTORY, COALESCE(SUM(S.SHIPPING_QUANTITY), 0) AS LAST_15_DAYS_SALES FROM INVENTORY_UNPVT I LEFT JOIN snitch_db.maplemonk.Store_Fact_items_offline S ON S.BRANCH_CODE = I.BRANCH_CODE AND UPPER(S.SKU_GROUP) = I.SKU_GROUP AND CASE WHEN S.SIZE = \'XXXL\' THEN \'3XL\' WHEN S.SIZE = \'XXL\' THEN \'XXL\' WHEN S.SIZE = \'XS\' THEN \'XS\' WHEN S.SIZE = \'XL\' THEN \'XL\' WHEN S.SIZE = \'S\' THEN \'S\' WHEN S.SIZE = \'M\' THEN \'M\' WHEN S.SIZE = \'L\' THEN \'L\' WHEN S.SIZE = \'6XL\' THEN \'6XL\' WHEN S.SIZE = \'5XL\' THEN \'5XL\' WHEN S.SIZE = \'4XL\' THEN \'4XL\' WHEN S.SIZE = \'3XL\' THEN \'3XL\' WHEN S.SIZE = \'2XL\' THEN \'XXL\' WHEN S.SIZE = \'06XL\' THEN \'6XL\' WHEN S.SIZE = \'01XL\' THEN \'XL\' WHEN S.SIZE = \'46\' THEN \'6XL\' WHEN S.SIZE = \'44\' THEN \'5XL\' WHEN S.SIZE = \'42\' THEN \'4XL\' WHEN S.SIZE = \'40\' THEN \'3XL\' WHEN S.SIZE = \'38\' THEN \'XXL\' WHEN S.SIZE = \'36\' THEN \'XL\' WHEN S.SIZE = \'34\' THEN \'L\' WHEN S.SIZE = \'32\' THEN \'M\' WHEN S.SIZE = \'30\' THEN \'S\' WHEN S.SIZE = \'28\' THEN \'XS\' ELSE \'NO_MATCH\' END = I.SIZE AND S.ORDER_DATE > I.DATE AND S.ORDER_DATE <= LEAST(DATEADD(DAY, 15, I.DATE), CURRENT_DATE) GROUP BY I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, LAST_15_DAYS_SALES, LEAST(LAST_15_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM LAST60D_STR WHERE SNAPSHOT_DATE = CURRENT_DATE - 60 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), today_inv AS ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, DATE AS SNAPSHOT_DATE, INVENTORY AS CLOSING_INVENTORY_TODAY FROM INVENTORY_UNPVT WHERE DATE = CURRENT_DATE ) SELECT COALESCE( A.MARKETPLACE_MAPPED, B.MARKETPLACE_MAPPED, C.MARKETPLACE_MAPPED, D.MARKETPLACE_MAPPED, E.MARKETPLACE_MAPPED ) AS MARKETPLACE_MAPPED, COALESCE( A.CATEGORY, B.CATEGORY, C.CATEGORY, D.CATEGORY, E.CATEGORY ) AS CATEGORY, COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE, D.BRANCH_CODE, E.BRANCH_CODE) AS BRANCH_CODE, COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP, D.SKU_GROUP, E.SKU_GROUP) AS SKU_GROUP, COALESCE(A.SIZE, B.SIZE, C.SIZE, D.SIZE, E.SIZE) AS SIZE, COALESCE(A.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L15D, COALESCE(B.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L30D, COALESCE(C.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L45D, COALESCE(D.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L60D, COALESCE(E.CLOSING_INVENTORY_TODAY, 0) AS CLOSING_INVENTORY_TODAY, COALESCE(A.LAST_15_DAYS_SALES, 0) AS SALES_D0_15, COALESCE(B.LAST_15_DAYS_SALES, 0) AS SALES_D15_30, COALESCE(C.LAST_15_DAYS_SALES, 0) AS SALES_D30_45, COALESCE(D.LAST_15_DAYS_SALES, 0) AS SALES_D45_60, COALESCE(A.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D0_15, COALESCE(B.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D15_30, COALESCE(C.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D30_45, COALESCE(D.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D45_60 FROM last_15 A FULL OUTER JOIN last_30 B ON A.BRANCH_CODE = B.BRANCH_CODE AND A.SKU_GROUP = B.SKU_GROUP AND A.SIZE = B.SIZE FULL OUTER JOIN last_45 C ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE) = C.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP) = C.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE) = C.SIZE FULL OUTER JOIN last_60 D ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE) = D.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP) = D.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE, C.SIZE) = D.SIZE FULL OUTER JOIN today_inv E ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE, D.BRANCH_CODE) = E.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP, D.SKU_GROUP) = E.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE, C.SIZE, D.SIZE) = E.SIZE ) a LEFT JOIN ( SELECT * FROM ( SELECT Category AS product_type, sku_group, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1 DESC) rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) b ON LOWER(a.SKU_GROUP) = LOWER(b.sku_group) ) WHERE MARKETPLACE_MAPPED LIKE \'%COCO%\' OR MARKETPLACE_MAPPED LIKE \'%COFO%\' OR MARKETPLACE_MAPPED LIKE \'%FOCO%\';",
                    "transaction": true
                }
            ) }}
